css:
/* Design system generated by Taster. Load after registry/src/tokens.css; components read the alias tokens only. */
/* density airy, contrast standard, roundness pillow, type-expression poster, color-restraint achromatic, elevation raised, motion still, stroke light; light scheme */
:root, :root[data-theme] {
  --accent-fg: #ffffff;
  --success: #007834;
  --danger: #b02b27;
  --destructive: #b02b27;
  --delta-up: #007834;
  --delta-down: #b02b27;
  --background: oklch(0.985 0 0);
  --foreground: oklch(0.18 0 0);
  --card-foreground: oklch(0.18 0 0);
  --popover-foreground: oklch(0.18 0 0);
  --primary: oklch(0.205 0 0);
  --primary-foreground: oklch(0.985 0 0);
  --secondary-foreground: oklch(0.18 0 0);
  --accent-foreground: oklch(0.18 0 0);
  --ring: oklch(0.556 0 0);
  --sidebar: oklch(0.97 0 0);
  --sidebar-foreground: oklch(0.18 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.94 0 0);
  --sidebar-accent-foreground: oklch(0.18 0 0);
  --sidebar-border: oklch(0 0 0 / 10%);
  --sidebar-ring: oklch(0.556 0 0);
  --info: oklch(0.205 0 0);
  --info-foreground: oklch(0.985 0 0);
  --warning: oklch(0.55 0.13 50);
  --warning-foreground: oklch(0.985 0 0);
  --sp-1: 4px;
  --sp-2: 10px;
  --sp-3: 14px;
  --sp-4: 18px;
  --sp-5: 22px;
  --sp-6: 28px;
  --sp-8: 36px;
  --sp-12: 54px;
  --sp-16: 72px;
  --control-sm: 34px;
  --control-md: 38px;
  --lh-normal: 1.55;
  --lh-snug: 1.325;
  --muted-foreground: oklch(0.49 0 0);
  --text-subtle: oklch(0.51 0 0);
  --muted: oklch(0.95 0 0);
  --secondary: oklch(0.95 0 0);
  --radius: 1.25rem;
  --r-sm: 12px;
  --r-md: 16px;
  --r-card: 20px;
  --r-xl: 28px;
  --r-2xl: 36px;
  --r-3xl: 44px;
  --r-4xl: 52px;
  --font: 'IBM Plex Sans', 'IBM Plex Sans KR', -apple-system, system-ui, sans-serif;
  --t-display: 60px;
  --t-h1: 44px;
  --t-h2: 32px;
  --t-title: 18px;
  --lh-tight: 1;
  --w-semi: 700;
  --brand: #4c1d95;
  --highlight: oklch(0.45 0 0);
  --accent-soft: oklch(0.38 0.178 293.745 / 12%);
  --chart-1: oklch(0.25 0 0);
  --chart-2: oklch(0.4 0 0);
  --chart-3: oklch(0.52 0 0);
  --chart-4: oklch(0.64 0 0);
  --chart-5: oklch(0.76 0 0);
  --chart-6: oklch(0.86 0 0);
  --success-soft: oklch(0.5 0.139 149.741 / 12%);
  --warning-soft: oklch(0.55 0.13 50 / 12%);
  --danger-soft: oklch(0.501 0.17 27.189 / 12%);
  --sh-card: 0 1px 3px rgba(0,0,0,.08), 0 2px 6px rgba(0,0,0,.06);
  --sh-pop: 0 10px 30px rgba(0,0,0,.14);
  --card: oklch(1 0 0);
  --popover: oklch(1 0 0);
  --scrim: oklch(0 0 0 / 45%);
  --dur-press: 100ms;
  --dur-tooltip: 100ms;
  --dur-dropdown: 120ms;
  --dur-modal: 150ms;
  --stagger-step: 0ms;
  --press-scale: 1;
  --enter-scale: 1;
  --enter-offset: 0px;
  --blur-mask: 0px;
  --border: oklch(0 0 0 / 12%);
  --border-soft: rgba(0, 0, 0, 0.08);
  --input: oklch(0 0 0 / 24%);
  --icon-stroke: 2;
}
.theme-dark, .theme-light {
  --brand: #4c1d95;
  --accent-fg: #ffffff;
  --font: 'IBM Plex Sans', 'IBM Plex Sans KR', -apple-system, system-ui, sans-serif;
  --success: #007834;
  --danger: #b02b27;
  --destructive: #b02b27;
  --delta-up: #007834;
  --delta-down: #b02b27;
}
@media (prefers-reduced-motion: reduce) {
  :root, :root[data-theme] {
    --dur-press: 1ms;
    --dur-tooltip: 1ms;
    --dur-dropdown: 1ms;
    --dur-modal: 1ms;
    --stagger-step: 0ms;
    --press-scale: 1;
    --enter-scale: 1;
    --enter-offset: 0px;
    --blur-mask: 0px;
  }
}
@media (prefers-reduced-transparency: reduce) {
  :root, :root[data-theme] {
    --bg-elev: var(--bg-sunken);
    --scrim: oklch(0 0 0 / 80%);
  }
}
